import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { durationMinutes, isBefore, parseInstant } from '../../shared/time.js';
import * as roomRepository from '../rooms/repository.js';
import * as userRepository from '../users/repository.js';
import * as repository from './repository.js';
import { BOOKING_CANCELLED, MAX_DURATION_MINUTES, MIN_DURATION_MINUTES } from './schema.js';
import type {
  AvailabilityQueryInput,
  AvailabilityResult,
  CreateBookingInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

async function assertRoomExists(roomId: string): Promise<void> {
  const room = await roomRepository.findById(roomId);
  if (!room) {
    throw notFound('Room');
  }
}

async function assertUserExists(userId: string): Promise<void> {
  const user = await userRepository.findById(userId);
  if (!user) {
    throw notFound('User');
  }
}

function assertBookableWindow(startsAt: Date, endsAt: Date): void {
  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('endsAt must be after startsAt');
  }
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('startsAt cannot be in the past');
  }
  const minutes = durationMinutes(startsAt, endsAt);
  if (minutes < MIN_DURATION_MINUTES || minutes > MAX_DURATION_MINUTES) {
    throw validationFailed(
      `Booking duration must be between ${MIN_DURATION_MINUTES} and ${MAX_DURATION_MINUTES} minutes`,
    );
  }
}

async function assertNoConflict(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Promise<void> {
  const conflict = await repository.findOverlapping(roomId, startsAt, endsAt, excludeId);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);

  assertBookableWindow(startsAt, endsAt);
  await assertRoomExists(input.roomId);
  await assertUserExists(input.userId);
  await assertNoConflict(input.roomId, startsAt, endsAt);

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

